export const reducerLogger = (reducer, onBeforeAction, onAfterAction) => {
    const innerReducer = (state, action) => {
        onBeforeAction ? onBeforeAction(state, action) : console.log(`Before '${action.type}':`, state, action.payload);
        const res = reducer(state, action);
        onAfterAction ? onAfterAction(res, action) : console.log(`After '${action.type}':`, state, action.payload);
        return res;
    };
    return innerReducer;
};
